import { expect, test } from "@playwright/test";

type RuntimeMetrics = {
  host: { width: number; height: number };
  canvas: { width: number; height: number; cssWidth: number; cssHeight: number };
  engineStatus: string | null;
  modelVersion: string | null;
  view: string | null;
  drawCalls: number;
  triangles: number;
  staticObjectCount: number;
};

const assets = [
  "/models/drums/drum-kit-shell-set.glb",
  "/models/drums/hands/left-hold.glb",
  "/models/drums/hands/right-hold.glb",
];

function actionableConsole(message: import("@playwright/test").ConsoleMessage) {
  return ["error", "warning"].includes(message.type()) && !message.text().includes("GL Driver Message");
}

async function waitForModelAssets(page: import("@playwright/test").Page) {
  await expect
    .poll(() => page.evaluate((urls) => performance.getEntriesByType("resource")
      .map((entry) => entry.name)
      .filter((name) => urls.some((url) => name.includes(url))).length, assets))
    .toBe(3);
}

async function metrics(page: import("@playwright/test").Page): Promise<RuntimeMetrics> {
  return page.locator(".drum-kit-canvas").evaluate((host) => {
    const canvas = host.querySelector("canvas")!;
    const hostRect = host.getBoundingClientRect();
    const canvasRect = canvas.getBoundingClientRect();
    const data = host.dataset;
    return {
      host: { width: hostRect.width, height: hostRect.height },
      canvas: { width: canvas.width, height: canvas.height, cssWidth: canvasRect.width, cssHeight: canvasRect.height },
      engineStatus: data.engineStatus ?? null,
      modelVersion: data.modelVersion ?? null,
      view: data.view ?? null,
      drawCalls: Number(data.drawCalls),
      triangles: Number(data.triangles),
      staticObjectCount: Number(data.staticObjectCount),
    };
  });
}

test.describe("licensed drum model runtime", () => {
  test("loads the licensed kit and hands within v26 rendering caps", async ({ page }) => {
    const consoleProblems: string[] = [];
    const requestProblems: string[] = [];
    page.on("console", (message) => {
      if (actionableConsole(message)) consoleProblems.push(`${message.type()}: ${message.text()}`);
    });
    page.on("requestfailed", (request) => requestProblems.push(`${request.url()}: ${request.failure()?.errorText}`));
    await page.setViewportSize({ width: 807, height: 361 });
    await page.goto("/kit");
    await expect(page.locator(".drum-kit-canvas")).toHaveAttribute("data-engine-status", "ready");
    await waitForModelAssets(page);
    await page.waitForTimeout(250);
    const result = await metrics(page);
    console.log(`KIT_METRICS ${JSON.stringify(result)}`);
    expect(result.modelVersion).toBe("professional-v27");
    expect(result.view).toBe("showcase");
    expect(result.drawCalls).toBeLessThanOrEqual(107);
    expect(result.triangles).toBeLessThanOrEqual(20140);
    expect(result.staticObjectCount).toBeGreaterThan(0);
    await page.locator(".drum-kit-canvas canvas").screenshot({ path: "output/playwright/drum-model-qa-licensed-v1-final/runtime/kit-showcase-807x361.png" });
    const canvas = page.locator(".drum-kit-canvas canvas");
    await canvas.focus();
    for (const key of ["Space", "f", "j", "k", "l"]) await page.keyboard.press(key);
    for (const point of [{ x: 243, y: 255 }, { x: 184, y: 224 }, { x: 138, y: 126 }, { x: 250, y: 175 }, { x: 365, y: 91 }]) {
      await canvas.click({ position: point, force: true });
    }
    expect(consoleProblems).toEqual([]);
    expect(requestProblems).toEqual([]);
  });

  test("Practice supports keyboard and physical-target pointer interaction with a visible snare stroke", async ({ page }) => {
    const problems: string[] = [];
    page.on("console", (message) => {
      if (actionableConsole(message)) problems.push(`${message.type()}: ${message.text()}`);
    });
    await page.setViewportSize({ width: 844, height: 340 });
    await page.goto("/practice");
    const canvas = page.locator(".drum-kit-canvas canvas");
    await expect(canvas).toBeVisible();
    await expect(page.locator(".drum-kit-canvas")).toHaveAttribute("data-engine-status", "ready");
    await waitForModelAssets(page);
    await page.waitForTimeout(250);
    const result = await metrics(page);
    console.log(`PRACTICE_METRICS ${JSON.stringify(result)}`);
    expect(result.view).toBe("player");
    expect(result.drawCalls).toBeLessThanOrEqual(105);
    expect(result.triangles).toBeLessThanOrEqual(20004);
    await canvas.screenshot({ path: "output/playwright/drum-model-qa-licensed-v1-final/runtime/practice-idle-844x340.png" });

    await page.getByRole("button", { name: "Start 4-count" }).click();
    await expect(page.locator(".mode-pill")).toHaveText("count-in");
    await page.evaluate(() => window.advanceTime?.(4200));
    await expect(page.locator(".mode-pill")).toHaveText("playing");
    await page.keyboard.press("f");
    await page.waitForTimeout(65);
    await canvas.screenshot({ path: "output/playwright/drum-model-qa-licensed-v1-final/runtime/practice-snare-hit-844x340.png" });
    await page.waitForTimeout(500);
    await canvas.screenshot({ path: "output/playwright/drum-model-qa-licensed-v1-final/runtime/practice-rebound-844x340.png" });
    expect(problems).toEqual([]);
  });

  test("fallback remains renderable and navigation disposes old canvases", async ({ browser }) => {
    const context = await browser.newContext({ viewport: { width: 844, height: 340 } });
    const page = await context.newPage();
    const expectedFallbackWarnings: string[] = [];
    const unexpected: string[] = [];
    page.on("console", (message) => {
      if (message.type() === "warning" && message.text().includes("licensed model load failed; keeping procedural fallback")) expectedFallbackWarnings.push(message.text());
      else if (actionableConsole(message) && !message.text().includes("Failed to load resource")) unexpected.push(`${message.type()}: ${message.text()}`);
    });
    await page.route("**/models/drums/**/*.glb", (route) => route.abort("failed"));
    await page.goto("/kit");
    await expect(page.locator(".drum-kit-canvas")).toHaveAttribute("data-engine-status", "ready");
    await expect(page.locator("canvas")).toHaveCount(1);
    await expect.poll(() => expectedFallbackWarnings.length).toBeGreaterThan(0);
    await page.unroute("**/models/drums/**/*.glb");
    await page.goto("/practice");
    await expect(page.locator("canvas")).toHaveCount(1);
    await expect(page.locator(".drum-kit-canvas")).toHaveAttribute("data-engine-status", "ready");
    await page.goto("/trainer");
    await expect(page.locator("canvas")).toHaveCount(1);
    await expect(page.locator(".drum-kit-canvas")).toHaveAttribute("data-engine-status", "ready");
    expect(unexpected).toEqual([]);
    await context.close();
  });
});
